    width: 100%;
    max-width: 600px;
}

h1 {
    font-size: 2rem;
    margin-bottom: 2rem;
    text-align: center;
}

.image-card {
    background-color: var(--surface-color);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 1.5rem;
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.4);
}

.image-container {
    background-color: #000;
    border-radius: 8px;
    overflow: hidden;
    margin-bottom: 1.5rem;
