    margin-bottom: 2rem;
}

.dialog-actions {
    display: flex;
    justify-content: flex-end;
    gap: 1rem;
}

/* Forced Colors Adaptation */
@media (forced-colors: active) {
    dialog {
        border: 2px solid ButtonBorder;
    }
    button {
        border: 1px solid ButtonBorder;
    }
    .image-card {
        border: 2px solid CanvasText;
    }
}
