const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  let browser;
  try {
    browser = await chromium.launch();
  } catch (e) {
    // If browser is missing, try to install it silently
    const execSync = require('child_process').execSync;
    execSync('npx playwright install chromium >/dev/null 2>&1');
    browser = await chromium.launch();
  }

  const page = await browser.newPage();
  const htmlPath = path.resolve('index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf8');

  await page.setContent(htmlContent, { waitUntil: 'load' });

  // Inject axe-core
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Run axe
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  const output = {
    wcag: wcag.map(v => ({
      id: v.id,
      impact: v.impact,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    })),
    bp: bp.map(v => ({
      id: v.id,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    }))
  };

  console.log(JSON.stringify(output, null, 2));
  process.exit(wcag.length > 0 ? 1 : 0);
})();

