    const trigger = document.querySelector('.trigger');
    const dialog = document.getElementById('delete-dialog');
    const cancelBtn = document.getElementById('cancel-btn');
    const confirmDeleteBtn = document.getElementById('confirm-delete-btn');

    if (!trigger || !dialog || !cancelBtn || !confirmDeleteBtn) {
        console.error('Required elements not found');
        return;
    }

    /**
     * Opens the confirmation dialog.
     * Native .showModal() handles focus trap and backdrop.
     */
    trigger.addEventListener('click', () => {
        dialog.showModal();
        // Native behavior focuses the first focusable element (Cancel button).
        // This is preferred for destructive actions.
    });

    /**
     * Closes the dialog without action.
     */
    cancelBtn.addEventListener('click', () => {
        dialog.close('cancel');
    });

    /**
     * Handles the deletion confirmation.
     */
    confirmDeleteBtn.addEventListener('click', () => {
        // Implementation of deletion would go here.
        // For this demo, we'll update the UI to show success.

        dialog.close('delete');

        const imageCard = document.querySelector('.image-card');
        if (imageCard) {
            imageCard.setAttribute('role', 'status');
            imageCard.setAttribute('aria-live', 'polite');
            imageCard.innerHTML = `
                <div style="text-align: center; padding: 2rem;">
                    <h2 style="color: var(--danger-color);">Image Deleted</h2>
                    <p>The image has been successfully removed from your library.</p>
                    <button type="button" onclick="location.reload()" class="btn-secondary" style="margin-top: 1rem;">Reset Demo</button>
                </div>
            `;
        }
    });

    /**
     * Close dialog if clicking the backdrop.
     * Native dialog 'click' event bubbles from the backdrop (which is part of the dialog element).
     */
    dialog.addEventListener('click', (event) => {
        const rect = dialog.getBoundingClientRect();
        const isInDialog = (
            rect.top <= event.clientY &&
            event.clientY <= rect.top + rect.height &&
            rect.left <= event.clientX &&
            event.clientX <= rect.left + rect.width
        );

        if (!isInDialog) {
            dialog.close();
        }
    });

    /**
     * Handle the 'close' event for any cleanup or focus management
     * if the trigger were to be removed from the DOM.
     */
    dialog.addEventListener('close', () => {
        console.log('Dialog closed with return value:', dialog.returnValue);
        // Focus is automatically restored to the trigger by the browser
        // since we used .showModal() and the trigger still exists.
    });
});
